export PATH="$HOME/.bun/bin:$PATH"; cd /workspace; gbrain setup claude-code --json > /tmp/setup.json 2>/tmp/setup.err; echo "exit=$?"; cat /tmp/setup.err | head -80; python3 -c "
import json;d=json.load(open('/tmp/setup.json'))
print(json.dumps({k:d.get(k) for k in ['state','states','verify','preserved','notes']},indent=1)[:3000])
for n in d.get('notices',[]): print(n.get('code'), n.get('kind')); print(n.get('user_message'))
"

export PATH="$HOME/.bun/bin:$PATH"; bun -e '
const d=JSON.parse(require("fs").readFileSync("/tmp/setup.json","utf8"));
console.log(JSON.stringify({state:d.state,verify:d.verify,preserved:d.preserved,instructions:d.instructions,notes:d.notes},null,1).slice(0,3000));
for(const n of d.notices||[]){console.log("NOTICE",n.code,n.kind);console.log(n.user_message);for(const x of n.decisions||[])console.log(" -",x.id,"default:",x.default, JSON.stringify(x.in_effect??x.applied??""))}'; echo ---; cat /harness-state/claude/settings.json

